+enum LabelPatchKind: uint8_t {
+  LPK_FULL_ADDRESS = 0,
+  LPK_COMPRESSED_OFFSET_16 = 1,
+  LPK_COMPRESSED_OFFSET_32 = 2
+};
+
+template <typename T>
+static inline T jt_cast(intptr_t value) {
+  return checked_cast<T>(value);
+}
